/* ---------- Tools and connections ---------- */
/* the tools the agent can reach, each with an Off, Ask or Allow switch. The card sits on two columns (owner, 18 Nov), its
   content 16px from every edge: the head's neutral mark in a 28px column with each tool's mark under it, and the title and
   each tool's words 12px after it; the switches, Reconnect and Test all's words end on the content's right edge, and each
   row shares one centre line. A row is not a button, so it has no hover fill. A tool's state is a small dot after its name,
   beside it and never over its mark: green while it is connected, red once it has failed, a turning ring while it is tested
   (the -mark colours, 3:1), none while it is off, when the row dims. Its mark is the tool's logo on a white tile, or its icon
   on a vivid tile of its colour (white or the colour's own ink on it). A test's progress and result are a line in the foot,
   beside Connect a tool. The card grows and shrinks with its rows (grow()) */
.hnx{padding:var(--dm-s-4);display:flex;flex-direction:column}
.hnx.growing:has(.pop.open){overflow:visible}
.hnx-h{display:flex;align-items:center;gap:var(--dm-s-3);padding-bottom:var(--dm-s-2)}
.hnx-hi{width:28px;height:28px;display:grid;place-items:center;flex:none;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));color:var(--dm-fg2);background:var(--dm-chip)}
.hnx-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.hnx-h b{font-weight:500;font-size:14px;line-height:20px}
/* a test's progress and result sit in the foot, beside Connect a tool, its words ending on the content's right edge */
/* the foot sits under a hairline in Soft and Blueprint (owner, 21 Nov: "blueprint should have divider lines at the bottom"),
   its button's words 16px from the hairline and 16px from the card's bottom edge (owner, 23 Nov): the ghost button's 32px box
   reaches 6px round its words, so the foot has 10px above it and reaches 6px into the card's bottom padding. Clean's is a foot
   strip (below) */
.hnx-ft{display:flex;align-items:center;gap:var(--dm-s-3);margin-top:0;margin-bottom:-6px;padding-top:10px;border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent)}
.hnx-st{display:flex;align-items:center;gap:5px;min-width:0;margin-left:auto;height:18px;font-size:12px;line-height:18px;white-space:nowrap}
.hnx-st>span{min-width:0;overflow:hidden;text-overflow:ellipsis}
.hnx-st .i{flex:none;color:var(--dm-ok-mark)}
.hnx-st .shim{font-size:inherit}
.hnx-st:empty{display:none}
/* Test all: its hover box ends on the content's right edge (a box that fills keeps the card's 16px); it is as wide as its
   words, and eases to its new width when they change */
.hnx-test{flex:none;overflow:hidden}
.hnx-test .spin{width:11px;height:11px}
.hnx-list{display:flex;flex-direction:column}
.hnx-t{display:grid;grid-template-columns:28px minmax(0,1fr) auto;align-items:center;column-gap:var(--dm-s-3);padding:var(--dm-s-2) 0;font-size:13px}
.hnx-t .ic{width:28px;height:28px;border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));display:grid;place-items:center;transition:opacity var(--dm-t-fast) var(--dm-ease)}
.hnx-t .ic.brandic{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg)}
.hnx-t .ic .brand{width:15px;height:15px}
.hnx-t .t{min-width:0;display:flex;flex-direction:column}
.hnx-t .nm{display:flex;align-items:center;gap:6px;min-width:0;line-height:20px;transition:color var(--dm-t-fast) var(--dm-ease)}
.hnx-t .nm>span:first-child{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hnx-t .d{font-size:12px;line-height:18px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.hnx-t.err .d{color:var(--dm-bad);white-space:normal;text-wrap:pretty}
/* the state: a dot after the name (connected, failed), a turning ring while it is tested */
.hnx-dot{flex:none;width:6px;height:6px;border-radius:50%;background:var(--dm-ok-mark);transition:background-color var(--dm-t-fast) var(--dm-ease),opacity var(--dm-t-fast) var(--dm-ease)}
.hnx-t.err .hnx-dot{background:var(--dm-bad-mark)}
.hnx-t.off .hnx-dot{opacity:0}
.hnx-t.chk .hnx-dot{width:10px;height:10px;box-sizing:border-box;background:none;border:1.5px solid var(--dm-accent-mark,var(--dm-accent));border-right-color:transparent;opacity:1;animation:rot .8s linear infinite;transition:none}
/* the turning ring stays round in Blueprint, as its other loaders do */
:root:not([data-style="soft"],[data-style="clean"]) .hnx-t.chk .hnx-dot:not(:where([data-style="soft"],[data-style="soft"] *,[data-style="clean"],[data-style="clean"] *)){border-radius:50%!important}
/* off: the mark fades and the name steps down to muted, so the text stays readable */
.hnx-t.off .ic{opacity:.5}
.hnx-t.off .nm{color:var(--dm-muted)}
/* the same pill switch as every other segmented switch */
.hnx-pm{display:grid;grid-template-columns:repeat(3,auto);padding:2px;border-radius:var(--dm-r-pill);background:var(--dm-chip);position:relative}
.hnx-pm button{position:relative;z-index:1;height:24px;padding:0 9px;border-radius:var(--dm-r-pill);font-size:11.5px;color:var(--dm-muted);transition:color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){.hnx-pm button:hover{color:var(--dm-fg2)}}
.hnx-pm button[aria-pressed="true"]{color:var(--dm-fg)}
.hnx-pm button:focus-visible{outline-offset:-2px}
.hnx-pm .kn{position:absolute;top:2px;bottom:2px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:0 1px 2px rgba(0,0,0,.08);transition:left var(--dm-t) var(--dm-ease),width var(--dm-t) var(--dm-ease)}
.hnx-t .pill .spin{width:11px;height:11px}
/* Connect a tool: its + centred in the marks' column and its words on the title's; the hover box starts on the content's edge */
.hnx-add{display:flex;align-items:center;gap:var(--dm-s-3);flex:none;height:32px;padding:0 var(--dm-s-3) 0 0;font-size:13px;color:var(--dm-fg2);border-radius:calc(8px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
.hnx-add>.i{width:28px;padding:0 8px;box-sizing:border-box}
.hnx-add[aria-expanded="true"]{color:var(--dm-fg);background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.hnx-add:hover{color:var(--dm-fg);background:var(--dm-row)}}
.hnx-pop{min-width:220px}
/* its motion (the core's motion pieces, owner, 26 Nov): Connect a tool's menu grows out of its button and goes back quicker,
   its rows settle one after another and one highlight glides between them (.mx-pop, .mx-rows, .mx-glide); a press shows at once
   (.mx-press); Test all eases to the width of its new words on the spring (mxWidth()); the card grows on the spring (.mx-grow) */
.hnx-pop .mi .brand{width:12px;height:12px}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.hnx :is(.ib,.pill):active,:root[data-style="clean"] .hnx .ib:active,:root [data-style="clean"] .hnx .ib:active,:root [data-style="clean"].hnx .ib:active{transform:none}
/* Clean (owner, 17 and 18 Nov): the head an off-white strip with a hairline under it, Test all a flat secondary button 16px
   from the strip's top and bottom (owner, 23 Nov) and from the card's right edge; the tools' marks one neutral grey with a hairline (their logos keep their own
   colours); Connect a tool a flat secondary button on an off-white foot strip, 16px from its top and bottom and 16px in from
   the sides like everything in the card (21 Nov); the content 16px in from each edge and 16px from each strip; the switch is Clean's, a white knob on a track with an inner shadow */
:root[data-style="clean"] .hnx.panel,:root [data-style="clean"] .hnx.panel,:root [data-style="clean"].hnx.panel{padding:0}
/* the strips' buttons sit on the content's columns (owner, 21 Nov: "why do the components on the left have all different
   alignment?", "same on the right"): Test all ends where the switches end, 16px in, and Connect a tool starts where the marks
   start, 16px in; the strips keep 16px above and below them too (owner, 23 Nov) */
:root[data-style="clean"] .hnx-h,:root [data-style="clean"] .hnx-h,:root [data-style="clean"].hnx-h{min-height:calc(28px + 2 * var(--dm-strip-y) + 1px);padding:var(--dm-strip-y) 16px;background:var(--dm-strip);border-bottom:1px solid var(--dm-line);border-radius:var(--dm-r-card) var(--dm-r-card) 0 0}
:root[data-style="clean"] .hnx-hi,:root [data-style="clean"] .hnx-hi,:root [data-style="clean"].hnx-hi{background:var(--dm-surface);box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .pill.hnx-test,:root [data-style="clean"] .pill.hnx-test,:root [data-style="clean"].pill.hnx-test{margin:0;color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .pill.hnx-test:hover,:root [data-style="clean"] .pill.hnx-test:hover,:root [data-style="clean"].pill.hnx-test:hover{background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .pill.hnx-test:active,:root [data-style="clean"] .pill.hnx-test:active,:root [data-style="clean"].pill.hnx-test:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .pill.hnx-test[disabled],:root [data-style="clean"] .pill.hnx-test[disabled],:root [data-style="clean"].pill.hnx-test[disabled]{color:var(--dm-muted);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .pill.hnx-test[disabled]:hover,:root [data-style="clean"] .pill.hnx-test[disabled]:hover,:root [data-style="clean"].pill.hnx-test[disabled]:hover{color:var(--dm-muted);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}}
:root[data-style="clean"] .hnx-st .i,:root [data-style="clean"] .hnx-st .i,:root [data-style="clean"].hnx-st .i{color:color-mix(in srgb,var(--dm-ok-mark) 80%,var(--dm-ok))}
:root[data-style="clean"] .hnx-list,:root [data-style="clean"] .hnx-list,:root [data-style="clean"].hnx-list{padding:var(--dm-s-2) var(--dm-s-4)}
:root[data-style="clean"] .hnx-t .ic,:root [data-style="clean"] .hnx-t .ic,:root [data-style="clean"].hnx-t .ic,:root[data-style="clean"] .hnx-t .ic.brandic,:root [data-style="clean"] .hnx-t .ic.brandic,:root [data-style="clean"].hnx-t .ic.brandic{background:var(--dm-surface)!important;color:var(--dm-fg2)!important;box-shadow:inset 0 0 0 1px var(--dm-hair);border-radius:10px}
:root[data-style="clean"] .hnx-pm,:root [data-style="clean"] .hnx-pm,:root [data-style="clean"].hnx-pm{background:var(--dm-chip);box-shadow:var(--dm-track-ring)}
:root[data-style="clean"] .hnx-pm .kn,:root [data-style="clean"] .hnx-pm .kn,:root [data-style="clean"].hnx-pm .kn{background:var(--dm-knob);box-shadow:var(--dm-knob-shadow);transition:left var(--dm-t) var(--dm-ease),width var(--dm-t) var(--dm-ease)}
:root[data-style="clean"] .hnx-pm button,:root [data-style="clean"] .hnx-pm button,:root [data-style="clean"].hnx-pm button{color:var(--dm-muted);font-weight:500;transition:color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .hnx-pm button[aria-pressed="true"],:root [data-style="clean"] .hnx-pm button[aria-pressed="true"],:root [data-style="clean"].hnx-pm button[aria-pressed="true"]{color:var(--dm-fg)}
:root[data-style="clean"] .hnx-ft,:root [data-style="clean"] .hnx-ft,:root [data-style="clean"].hnx-ft{margin-top:0;margin-bottom:0;padding:var(--dm-strip-y) var(--dm-s-4);background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card)}
:root[data-style="clean"] .hnx-add,:root [data-style="clean"] .hnx-add,:root [data-style="clean"].hnx-add{gap:6px;height:28px;margin:0;padding:0 12px 0 10px;border-radius:var(--dm-r-pill);font-weight:500;color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth);transition:box-shadow var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .hnx-add>.i,:root [data-style="clean"] .hnx-add>.i,:root [data-style="clean"].hnx-add>.i{width:12px;padding:0}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] :is(.hnx-add:hover,.hnx-add[aria-expanded="true"]),:root [data-style="clean"] :is(.hnx-add:hover,.hnx-add[aria-expanded="true"]),:root [data-style="clean"]:is(.hnx-add:hover,.hnx-add[aria-expanded="true"]){background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .hnx-add:active,:root [data-style="clean"] .hnx-add:active,:root [data-style="clean"].hnx-add:active{box-shadow:var(--dm-btn2-press)}
:root[data-style="clean"] .hnx-pop,:root [data-style="clean"] .hnx-pop,:root [data-style="clean"].hnx-pop{padding:6px;border-radius:var(--dm-r-card)}
:root[data-style="clean"] .hnx-pop .mi,:root [data-style="clean"] .hnx-pop .mi,:root [data-style="clean"].hnx-pop .mi{border-radius:calc(var(--dm-r-card) - 6px)}

DM.def('tool-connections', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{refresh}', I('refresh','xs')).replace('{plus}', I('plus','xs')).replace('{link}', I('link','xs'));
  // [mark, name, detail, tile colour (a vivid avatar colour, for a mark without a logo), permission 0 Off, 1 Ask, 2 Allow]
  let T = [
    ['@figma','Figma','Read and edit frames','',1],
    ['@github','GitHub','designme/web, PRs only','',0],
    ['@slack','Slack','#design, #launch','',1],
    ['db','Analytics','Read only, last 90 days','t',1],
    ['globe','Web search','Any public site','b',2]
  ];
  const ADD = [['table','Google Sheets','m'],['@linear','Linear',''],['@gmail','Gmail','']];
  const root = $('.hnx', r) || r, list = $('.hnx-list', r), st = $('.hnx-st', r), pop = $('.hnx-pop', r);
  const PM = ['Off','Ask','Allow'];
  // a tool's mark: its logo on a white tile, or its icon on a vivid tile of its colour, with white or the colour's own ink
  const mark = (m, k) => m[0] === '@' ? `<span class="ic brandic" aria-hidden="true">${BRAND[m.slice(1)]}</span>` : `<span class="ic" style="background:var(--dm-av-${k});color:var(--dm-av-${k}-ink)" aria-hidden="true">${I(m,'xs')}</span>`;
  function row(t){
    const el = html(`<div class="hnx-t${t[4] === 0 ? ' off' : ''}" role="listitem">${mark(t[0], t[3])}<span class="t"><span class="nm"><span>${t[1]}</span><i class="hnx-dot" aria-hidden="true"></i></span><span class="d">${t[2]}</span></span><div class="hnx-pm" role="group" aria-label="${t[1]} permission"><span class="kn"></span>${PM.map((p, i) => `<button aria-pressed="${i === t[4]}" data-tip="${['Agent cannot use it','Agent asks first','Agent uses it freely'][i]}">${p}</button>`).join('')}</div></div>`);
    const g = $('.hnx-pm', el), kn = $('.kn', g), bs = $$('button', g);
    // the knob slides when a choice changes; when the row first appears it is simply in place
    const place = now => { const b = bs[t[4]]; if (now) kn.style.transition = 'none'; kn.style.left = b.offsetLeft + 'px'; kn.style.width = b.offsetWidth + 'px'; if (now){ void kn.offsetWidth; kn.style.transition = ''; } };
    bs.forEach((b, i) => b.onclick = () => { t[4] = i; bs.forEach((x, j) => x.setAttribute('aria-pressed', j === i)); place(); el.classList.toggle('off', i === 0); count(); });
    // a click with the mouse doesn't take focus, so it never leaves a focus ring; the keyboard still reaches every option
    bs.forEach(b => b.onmousedown = e => e.preventDefault());
    requestAnimationFrame(() => place(true)); new ResizeObserver(() => place(true)).observe(g);
    el._t = t; return el;
  }
  // a test's line, in the foot beside Connect a tool, never a count that repeats the list (the owner's notes on batch 2):
  // while it runs, what it tests, in words that shimmer; once it has run, how many are healthy, with the green tick when
  // every one is. A change to a switch makes that result old, so the line goes again
  const write = (h, now) => { if (now) st.innerHTML = h; else swap(st, h, true); };
  const count = now => write('', now);
  const healthy = (ok, n) => write((ok === n ? I('ok','xs') : '') + `<span>${ok} of ${n} healthy</span>`);
  T.forEach(t => list.appendChild(row(t))); stagger([...list.children], 50); count(true);
  function menu(){ pop.innerHTML = ADD.length ? ADD.map((a, i) => `<button class="mi mx-press" role="menuitem" data-close data-i="${i}">${a[0][0] === '@' ? BRAND[a[0].slice(1)] : I(a[0],'xs')}<span>${a[1]}</span></button>`).join('') : '<div class="ph">All tools connected</div>';
    $$('.mi', pop).forEach(m => m.addEventListener('click', () => { const a = ADD.splice(+m.dataset.i, 1)[0]; const t = [a[0], a[1], 'Just connected', a[2], 1]; T.push(t); const el = row(t); list.appendChild(el); enter(el); count(); menu(); })); }
  menu();
  // a menu opens over the card from its button: down when it fits below, up when it doesn't and fits above or has more room
  // there (as placePop), within the stage's room, so it never spills over the card's caption under the stage (as Artifact
  // card's version menu). The side is set on the button just before the menu is placed
  const side = (btn, pop) => { const room = popRoom(btn), st = btn.closest('.stage-inner') || btn.closest('.stage');
    if (st){ const sr = st.getBoundingClientRect(), cs = getComputedStyle(st); room.top = Math.max(room.top, sr.top + parseFloat(cs.paddingTop)); room.bottom = Math.min(room.bottom, sr.bottom - parseFloat(cs.paddingBottom)); }
    const br = btn.getBoundingClientRect(), need = pop.offsetHeight + 12, below = room.bottom - br.bottom, above = br.top - room.top;
    btn.dataset.popPos = below < need && (above >= need || above > below) ? 'up' : 'down'; };
  const add = $('.hnx-add', r); c.on(add, 'click', () => { if (!pop.classList.contains('open')) side(add, pop); });
  // Test all: every connected tool's dot turns at once, and they settle one by one; only a failure changes its line. The
  // button is as wide as its words and eases to the new ones
  const test = $('.hnx-test', r);
  // (on the motion pieces' spring: mxWidth())
  const label = h => { const w0 = test.offsetWidth; test.innerHTML = h; if (!REDUCE && w0) mxWidth(test, w0); };
  const idle = I('refresh','xs') + '<span>Test all</span>';
  test.onclick = () => c.run(async () => {
    const rows = [...list.children].filter(el => el._t[4] > 0);
    test.disabled = true; label('<span class="spin"></span><span>Testing</span>'); write(`<span class="shim">Testing ${rows.length} connections</span>`);
    rows.forEach(el => el.classList.add('chk'));
    for (const el of rows){ await c.wait(600); el.classList.remove('chk');
      // the row turns red with its new words, not before them
      if (el._t[1] === 'Slack' && !el._t.ok){ el._bad = true; swap($('.d', el), 'Token expired. Reconnect to use it'); c.later(REDUCE ? 0 : 170, () => el.classList.add('err')); }
    }
    test.disabled = false; label(idle);
    healthy(rows.filter(el => !el._bad).length, rows.length);
    const bad = [...list.children].find(el => el._bad);
    // a second test finds the row already offering Reconnect, so it keeps that button
    const pm = bad && $('.hnx-pm', bad);
    if (pm){ const b = html(`<button class="pill accent sm">Reconnect</button>`); pm.replaceWith(b); enter(b);
      // while it reconnects it keeps its colour and its width, with a spinner in place of its word, and takes no second press
      b.onclick = () => c.run(async () => { if (b.getAttribute('aria-disabled')) return; b.setAttribute('aria-disabled', 'true'); b.setAttribute('aria-label', 'Reconnecting');
        const w0 = b.getBoundingClientRect().width; b.innerHTML = '<span class="spin"></span>'; b.style.width = w0 + 'px';
        await c.wait(900); bad.classList.remove('err'); bad._t.ok = true; const n = row(bad._t); bad.replaceWith(n); enter(n);
        const on = [...list.children].filter(el => el._t[4] > 0).length; healthy(on, on); }); }
  });
  // the card grows with its rows, and eases when a line wraps or Reconnect takes a switch's place (owner, 17 Nov: no room
  // kept for a later state)
  c.offs.push(grow(root));
  // the preview's story: test everything, Slack's token has expired, reconnect it, and every connection is healthy
  c.story(async s => {
    await s.beat(3);
    await s.tap(test); s.away();
    await s.until(() => $('.hnx-t.err .pill', list)); await s.beat(3);
    await s.tap($('.hnx-t.err .pill', list)); s.away();
    await s.until(() => !$('.hnx-t.err', list)); await s.beat(1);
  });
});
